from Crypto.Util.number import *

def rsa(p, q):
    msg = bytes_to_long(b"[REDACTED]")    
    n = p * q
    e = getPrime(16)
    c = pow(msg, e, n)
    p_q = p + q
    return c, e, n, p_q


p = getPrime(1024)
q = getPrime(1024)
c, e, n, p_q = rsa(p, q)


print("C =", hex(c))
print("E =", hex(e))
print("N =", hex(n))
print("P_Q =", hex(p_q))

